sample:
# 「件数が可変かどうか」で dynamic を使うべきかを判定するロジックの例です。
# 実務の判断基準を条件式にしてみます。

locals {
  rules = ["http", "https", "ssh", "monitoring"]

  # 件数が多い(またはリストが variable 由来)なら dynamic が候補になる
  decision = length(local.rules) >= 3 ? "dynamic" : "static"
}

output "decision" {
  value = local.decision
}

output "rule_count" {
  value = length(local.rules)
}

exercise.starter:
variable "rules" {
  type    = list(string)
  default = ["https", "ssh"]
}

# ここに output を 2 つ書く

exercise.answer:
variable "rules" {
  type    = list(string)
  default = ["https", "ssh"]
}

# 「件数が可変・多数なら dynamic、固定少数なら直書き」という実務の判断を
# length + 条件式で表しています。2 件なので static(直書きで十分)になります。
output "decision" {
  value = length(var.rules) >= 3 ? "dynamic" : "static"
}

output "rule_count" {
  value = length(var.rules)
}
